/* frontier (Tower of Valni / Lagdou Ruins) reinforcement tables: struct UnitDefinition
 * runs with embedded struct REDA (reinforcement) move data, NOT pixel graphics.
 * The REDA runs referenced by the UnitDef_*_ref tables are carved out into named,
 * typed `struct REDA REDAs_*[]` arrays (axis #6 editability + shiftability: the
 * .redas pointers become real symbol refs instead of base+offset casts).
 *
 * The leading UnitDefinition runs of each `frontier_df3_unitdef_b_NNN_*` slice are now
 * decoded into typed `struct UnitDefinition[]` initializers (scripts/type_frontier_unitdef.py);
 * the `.redas` pointer is a relocatable symbol reference (NULL for redaCount-0 entries,
 * else the exact carved REDA array). Where a slice's tail still holds uncarved REDA
 * arrays (not yet given named symbols), those bytes stay a byte-identical `_residue`
 * INCBIN, kept in the original section/order. Byte-identical to baserom; `make compare`
 * is the oracle.
 */

